// Magic Patch conversion test.
// pack: comfyui_essentials
// file: js/DisplayAny.js
// rule: widgets-array-mutation
//   line 21: this.widgets.length = 1;
//
// Run this file against BOTH the original and the converted source.
//
//   equivalence  must pass on both — the conversion changed no behaviour
//   fix          must FAIL on the original and PASS on the converted source
//
// `this.widgets.length = 1` truncates the array without going through
// `node.removeWidget`, so the widget store — the render and serialisation order
// under Nodes 2.0 — keeps every widget the node dropped. `widgets.remove(name)`
// runs teardown and keeps the store in step.
import { createPinia, setActivePinia } from 'pinia'
import { beforeEach, describe, expect, it } from 'vitest'

import { LGraph } from '@/lib/litegraph/src/LGraph'
import { LGraphNode } from '@/lib/litegraph/src/LGraphNode'
import { applyDefExtensions } from '@/platform/nodeApi/comfyApi'
import { useWidgetValueStore } from '@/stores/widgetValueStore'

const DISPLAY_ANY_DEF = {
  name: 'DisplayAny',
  display_name: 'Display Any',
  category: 'essentials/utilities',
  output: [],
  input: { required: {} }
}

describe('comfyui_essentials — js/DisplayAny.js', () => {
  let graph: LGraph
  let node: LGraphNode

  /**
   * Applies both registration paths, because this file runs against both
   * sources: the original patches the prototype from `beforeRegisterNodeDef`,
   * the conversion registers through `comfy.defs.extend`. Whichever source was
   * loaded, only one of these has anything to apply.
   */
  const applyPack = async (nodeType: typeof LGraphNode) => {
    const legacyApp = Reflect.get(globalThis, 'app')
    for (const extension of legacyApp?.extensions ?? []) {
      await extension.beforeRegisterNodeDef?.(
        nodeType,
        DISPLAY_ANY_DEF,
        legacyApp
      )
    }
    applyDefExtensions(nodeType, DISPLAY_ANY_DEF)
  }

  beforeEach(async () => {
    setActivePinia(createPinia())
    graph = new LGraph()

    class DisplayAny extends LGraphNode {
      constructor() {
        super('DisplayAny')
      }
    }
    await applyPack(DisplayAny)

    node = new DisplayAny()
    graph.add(node)
    node.addWidget('string', 'mode', 'raw', () => {})
    node.addWidget('string', 'stale', 'left over', () => {})
  })

  // The original truncates first and only then reaches `textWidget.inputEl` —
  // a property since renamed to `element` — so it throws there. Everything
  // asserted below is established before that point.
  const execute = () => {
    try {
      node.onExecuted?.({ text: ['hello ', 'world'] } as never)
    } catch {
      // The original's DOM fiddling is not what either section is asserting.
    }
  }

  const widgetNames = () => node.widgets?.map((w) => w.name) ?? []
  const storedOrder = () =>
    useWidgetValueStore().getNodeWidgetIds(graph.rootGraph.id, node.id)

  describe('equivalence — must pass before and after', () => {
    it('keeps the first widget and drops the ones after it', () => {
      execute()
      expect(widgetNames()).toContain('mode')
      expect(widgetNames()).not.toContain('stale')
    })

    it('does not accumulate widgets across executions', () => {
      execute()
      const settled = widgetNames().length
      execute()
      execute()
      expect(widgetNames()).toHaveLength(settled)
    })
  })

  describe('fix — must fail before, pass after', () => {
    it('drops the removed widget from the store render order', () => {
      execute()
      expect(storedOrder().some((id) => String(id).endsWith(':stale'))).toBe(
        false
      )
    })
  })
})
